package dayOne;

public class Average {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		float a = 5;
		float b = 4;
		float c = 9;
		float d = -4;
		float e = 2;
		
		System.out.println("Average of " + a + ", " +
				 + b + ", " +
				 + c + ", " +
				 + d + " and " +
				 + e + "\nis " + 
				 	((a + b + c + d + e) / 5));
	}

}
